const SKU_TO_IMAGE = new Map<string, string>();
const TITLE_TO_IMAGE = new Map<string, string>();

for (const entry of COMPLETE_CATALOG_MANIFEST) {
  if (entry.imagePath) {
    SKU_TO_IMAGE.set(entry.sku.toUpperCase(), entry.imagePath);
    SKU_TO_IMAGE.set(entry.sku, entry.imagePath);
    TITLE_TO_IMAGE.set(entry.productName.toLowerCase(), entry.imagePath);
    if (entry.productNameBn) {
      TITLE_TO_IMAGE.set(entry.productNameBn.toLowerCase(), entry.imagePath);
    }
  }
}

export function getManifestImageForSku(sku?: string | null): string | null {
  if (!sku) return null;
  return SKU_TO_IMAGE.get(sku.trim().toUpperCase()) || SKU_TO_IMAGE.get(sku.trim()) || null;
}

export function getManifestImageByTitle(title?: string | null): string | null {
  if (!title) return null;
  return TITLE_TO_IMAGE.get(title.trim().toLowerCase()) || null;
}
